import { PeerActionType, UserData } from './peerTypes';
import { Dispatch } from 'redux';
import { PeerConnection } from '../../helpers/peer';
import { ConnectionState, DataType, UserDetails } from '../../helpers/common';
import { addPlayerEvent, addPlayerToLobby, attack, choice, endTurn, move, playerDisconnected, reportVersionMismatch, useAbility } from '../connection/connectionActions';

export const startPeerSession = (id: string) => ({
    type: PeerActionType.PEER_SESSION_START, payload: id
});

export const stopPeerSession = () => ({
    type: PeerActionType.PEER_SESSION_STOP,
});

export const setLoading = (loading: boolean) => ({
    type: PeerActionType.PEER_LOADING, payload: loading
});

export const setUserData = (userData: UserData) => ({
    type: PeerActionType.PEER_SET_USER_DATA, payload: userData
});

export const startPeer: (previousId?: string) => (dispatch: Dispatch, getState: () => { connection: ConnectionState }) => Promise<string | undefined>
    = (previousId?: string) => (async (dispatch, getState) => {
        dispatch(setLoading(true));

        try {
            const id = await PeerConnection.startPeerSession(previousId);
            PeerConnection.onIncomingConnection((conn) => {
                const peerId = conn.peer;
                PeerConnection.onConnectionDisconnected(peerId, () => {
                    dispatch(playerDisconnected(peerId));
                });

                PeerConnection.onConnectionReceiveData(peerId, async (data) => {
                    //Receive data from users
                    switch (data.dataType) {
                        case DataType.VersionMismatch: {
                            const details = JSON.parse(data.body) as { receivedVersion?: string };
                            dispatch(reportVersionMismatch({ peerId, remoteVersion: data.appVersion ?? details.receivedVersion }));
                            return;
                        }
                        case DataType.UserDetails: {
                            const user = JSON.parse(data.body) as UserDetails;
                            const gameState = getState().connection.gameState;
                            if (user.rejoinGameId !== undefined && (!gameState.started || gameState.gameEnded
                                || gameState.gameId !== user.rejoinGameId
                                || !gameState.lobby.playerList.some(player => player.user.id === user.id
                                    && (!player.user.isBot || player.user.replacedPlayerName !== undefined)))) {
                                void PeerConnection.sendConnection(peerId, { dataType: DataType.GameRecoveryRejected, body: '' });
                                return;
                            }
                            dispatch(addPlayerToLobby(user));
                            return;
                        }
                        case DataType.PlayerAttack:
                            dispatch(attack(JSON.parse(data.body)));
                            return;
                        case DataType.PlayerChoice:
                            dispatch(choice(JSON.parse(data.body)));
                            return;
                        case DataType.PlayerMove:
                            dispatch(move(JSON.parse(data.body)));
                            return;
                        case DataType.PlayerEndTurn:
                            dispatch(endTurn(JSON.parse(data.body)));
                            return;
                        case DataType.PlayerAbility:
                            dispatch(useAbility(JSON.parse(data.body)));
                            return;
                        case DataType.PlayerEvent:
                            dispatch(addPlayerEvent(JSON.parse(data.body)));
                            return;
                    }
                });
            });

            dispatch(startPeerSession(id));
            dispatch(setLoading(false));
            return id;
        } catch (e) {
            console.log(e);
            dispatch(setLoading(false));
            return undefined;
        }
    });
